<div class="container page-space"><div class="eyebrow">ADMINISTRARE PLATFORMĂ</div><h1 class="page-title">Identitate și drepturi de administrare</h1><p><a class="text-link" href="/admin/updates">Actualizări și verificări <?=icon('arrow')?></a></p><?php if(\App\Core\Migrations::marketplace()):?><p><a href="/admin/marketplace">Administrează marketplace-ul</a></p><?php endif?><p><a href="/admin/standards">Ediții GS1 și copii private</a></p><?php if(\App\Core\Migrations::program()):?><p><a href="/admin/program">Contribuitori, parteneri și învățare</a></p><?php endif?><p><a href="/admin/sources">Surse externe și Open Food Facts</a></p><a class="back-link" href="/manage">← Spațiul producătorului</a><div class="admin-columns"><section class="panel"><h2>Organizații</h2><?php foreach($organizations as$o):?><article class="document-admin"><h3><?=e($o['display_name'])?></h3><p><?=e(ro_state($o['identity_status']))?></p><?php if(\App\Core\Migrations::anaf()):?><p><a href="/admin/organizations/<?=e($o['id'])?>">Datele fiscale ale organizației</a></p><?php endif?><form method="post" action="/admin" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="organization.verify"><input type="hidden" name="id" value="<?=e($o['id'])?>"><p class="small muted">Consemnează documentele consultate și modul în care ai verificat organizația și mandatul persoanei care o reprezintă. Nu include parole sau copii de acte personale.</p><label>Documente și verificări efectuate<textarea class="form-control" name="evidence" required maxlength="5000"></textarea></label><button class="btn btn-primary">Înregistrează verificarea</button></form></article><?php endforeach?></section><section class="panel"><h2>Drepturi GS1</h2><?php foreach($claims as$c):?><article class="document-admin"><h3><?=e($c['name'])?></h3><p><?=e($c['display_name'])?> · <?=e($c['gtin14'])?> · <?=e(ro_state($c['gtin_status']))?></p><p><?=e($c['claim_evidence'])?></p><form action="/admin" method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="gtin.review"><input type="hidden" name="id" value="<?=e($c['id'])?>"><label>Decizie<select name="state" class="form-select"><option value="verified">Drept verificat</option><option value="disputed">În dispută</option><option value="withdrawn">Drept retras</option></select></label><p class="small muted">Notează sursa verificării GTIN-ului și documentul care confirmă dreptul organizației de a-l administra.</p><label>Justificarea deciziei<textarea class="form-control" name="evidence" required maxlength="5000"></textarea></label><button class="btn btn-primary">Salvează decizia</button></form></article><?php endforeach?></section></div><section class="panel"><h2>Contacte pentru participarea verificată</h2><?php foreach($contacts as$contact):?><article class="document-admin"><h3><?=e($contact['display_name'])?></h3><p><?=e($contact['email'])?> · <?=$contact['email_verified']?'Contact verificat':'În așteptarea verificării'?></p><?php if(!$contact['email_verified']):?><form method="post" action="/admin" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="contact.verify"><input type="hidden" name="id" value="<?=e($contact['id'])?>"><label>Cum a fost verificată adresa de contact<textarea class="form-control" name="evidence" maxlength="5000" required></textarea></label><button class="btn btn-primary">Înregistrează verificarea contactului</button></form><?php endif?></article><?php endforeach?></section></div>
